+
+        @Override
+        public void onNext(HttpResult item) {
+            this.httpResult = item;
+        }
+
+        @Override
+        public void onError(Throwable throwable) {
+            this.throwable = throwable;
+        }
+
+        @Override
+        public void onComplete() {
+            this.completed = true;
+        }
+
+        private void requestData() {
+            subscription.request(1);
+        }
+    }
